function selectionHandles(){const b=selectionBounds();if(!b)return[];const z=cameraAt(current(),time).zoom;return[{mode:'scale',x:b.x,y:b.y,anchor:{x:b.x+b.w,y:b.y+b.h}},{mode:'scale',x:b.x+b.w,y:b.y,anchor:{x:b.x,y:b.y+b.h}},{mode:'scale',x:b.x+b.w,y:b.y+b.h,anchor:{x:b.x,y:b.y}},{mode:'scale',x:b.x,y:b.y+b.h,anchor:{x:b.x+b.w,y:b.y}},{mode:'rotate',x:b.cx,y:b.y-30*960/Math.max(1,stage.getBoundingClientRect().width)/z,anchor:{x:b.cx,y:b.cy}}]}
