stage.onpointermove=e=>{const drag=canvasInteraction;if(!drag)return;const p=pointerWorld(e,drag),dx=p.x-drag.p?.x,dy=p.y-drag.p?.y;if(drag.mode==='path'){pathPointerMove(p);return}if(Math.hypot(dx,dy)>1/cameraAt(current(),time).zoom)drag.moved=true;if(drag.mode==='pose'){poseJoint(drag.o,drag.key,p,drag.initial,drag.keyBase);draw();return}if(drag.mode==='marquee'){drag.end=p;draw();return}if(!drag.items?.length)return;if(drag.mode==='move'){let tx=dx,ty=dy;guideLines=[];if(snapEnabled){const primary=drag.items.find(i=>i.o.id===selected)||drag.items[0];for(const axis of['x','y']){const targets=[axis==='x'?480:270,...current().objects.filter(o=>!drag.items.some(i=>i.o===o)&&!o.hidden).map(o=>stateAt(o,time)[axis])],value=primary.display[axis]+(axis==='x'?tx:ty),target=targets.find(n=>Math.abs(n-value)<7/drag.camera.zoom);if(target!==undefined){if(axis==='x')tx=target-primary.display.x;else ty=target-primary.display.y;guideLines.push({axis,value:target})}}}applyCapturedTransform(drag.items,{translate:{x:tx,y:ty}})}else if(drag.mode==='scale'){const a=drag.anchor,ux=drag.p.x-a.x,uy=drag.p.y-a.y,f=((p.x-a.x)*ux+(p.y-a.y)*uy)/(ux*ux+uy*uy||1);applyCapturedTransform(drag.items,{scale:f,anchor:a})}else if(drag.mode==='rotate'){let angle=(Math.atan2(p.y-drag.anchor.y,p.x-drag.anchor.x)-Math.atan2(drag.p.y-drag.anchor.y,drag.p.x-drag.anchor.x))*180/Math.PI;if(e.shiftKey)angle=Math.round(angle/15)*15;applyCapturedTransform(drag.items,{rotation:angle,anchor:drag.anchor})}draw()};
