$('remove').onclick=()=>{const list=selectedLayers();if(!canTransform(list))return;const ids=new Set(list.map(o=>o.id));current().objects=current().objects.filter(o=>!ids.has(o.id));selectLayers([]);save();render()};$('duplicate').onclick=()=>{const list=selectedLayers();if(!canTransform(list))return;const copies=[],groups=new Map();for(const original of list){const copy=structuredClone(original);copy.id=uid();copy.keys.forEach(k=>k.v.x+=35);for(const pin of copy.footPins||[])pin.x+=35;if(copy.motionPath)copy.motionPath.points.forEach(p=>p.x+=35);if(copy.group){if(!groups.has(copy.group))groups.set(copy.group,copy.group+' copy '+uid().slice(0,4));copy.group=groups.get(copy.group)}current().objects.push(copy);duplicateLinkedAudio(original,copy);copies.push(copy.id)}selectLayers(copies);save();render()};
$('lockLayer').onclick=()=>{const list=selectedLayers();if(!list.length)return;const lock=!list.every(o=>o.locked);list.forEach(o=>o.locked=lock);save();render()};$('hideLayer').onclick=()=>{const list=selectedLayers();if(!canTransform(list))return;const hide=!list.every(o=>o.hidden);list.forEach(o=>o.hidden=hide);save();render()};$('assignGroup').onclick=()=>{const list=selectedLayers();if(!canTransform(list))return;list.forEach(o=>o.group=$('groupName').value.trim());save();render()};for(const[id,axis,target]of[['alignX','x',480],['alignY','y',270]])$(id).onclick=()=>{const b=selectionBounds();if(b)transformSelection({translate:{x:axis==='x'?target-b.cx:0,y:axis==='y'?target-b.cy:0}})};
for(const[id,direction]of[['front',1],['back',-1]])$(id).onclick=()=>{const list=selectedLayers();if(!canTransform(list))return;const ids=new Set(list.map(o=>o.id)),array=current().objects,order=direction>0?[...array.keys()].reverse():[...array.keys()];for(const i of order){const j=i+direction;if(j>=0&&j<array.length&&ids.has(array[i].id)&&!ids.has(array[j].id)&&!array[j].locked)[array[i],array[j]]=[array[j],array[i]]}save();render()};
const selectionExtras=renderExtras;renderExtras=function(){if(pathEditor&&pathEditor.sceneId!==current().id)clearCanvasInteraction();selectionExtras();document.querySelectorAll('[data-canvas-tool]').forEach(b=>b.classList.toggle('active',b.dataset.canvasTool===canvasMode));$('hint').textContent=canvasMode==='pose'?'Drag hands, elbows, knees, feet or the head · saved as keyframes':canvasMode==='path'?'Click to add route points · drag to adjust · Enter finishes · Esc cancels':'Shift-click or drag a selection box · resize and rotate using handles';const list=selectedLayers(),locked=list.some(o=>o.locked);$('selectionTools').hidden=list.length<2;$('selectionCount').textContent=list.length+' layers selected';$('selectionTools').querySelectorAll('input,button').forEach(e=>e.disabled=locked);if(list.length>1)$('selectionTitle').textContent=list.length+' selected layers';for(const id of['duplicate','remove','front','back','hideLayer','assignGroup','alignX','alignY'])$(id).disabled=!list.length||locked;if(list.length>1&&locked)$('controls').querySelectorAll('input,select,button').forEach(e=>e.disabled=true);document.querySelectorAll('#layers .layer').forEach((button,i)=>{const o=current().objects.slice().reverse()[i];button.classList.toggle('active',groupSelection.has(o.id));button.onclick=e=>{const ids=groupIds(o);if(e.shiftKey||e.ctrlKey||e.metaKey){const set=new Set(selectedLayers().map(o=>o.id));if(ids.every(id=>set.has(id)))ids.forEach(id=>set.delete(id));else ids.forEach(id=>set.add(id));selectLayers([...set],set.has(o.id)?o.id:null)}else selectLayers(ids,o.id);render()}})};
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||document.querySelector('dialog[open]')||recording)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'){e.preventDefault();selectLayers(current().objects.filter(o=>!o.hidden).map(o=>o.id));render()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='g'){e.preventDefault();e.shiftKey?ungroupSelectedLayers():groupSelectedLayers()}else if(['Delete','Backspace'].includes(e.key)){e.preventDefault();$('remove').click()}else if(e.key==='Escape'&&canvasInteraction){e.preventDefault();finishCanvasDrag(true)}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&selectedLayers().length&&!e.target.classList.contains('clip-diamond')&&!e.target.classList.contains('audio-fade')&&!e.target.classList.contains('timeline-marker')){e.preventDefault();const step=e.shiftKey?10:1;transformSelection({translate:{x:e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0,y:e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0}})}});
